export interface PlatformIconProps {
  platform?: GroupPlatform
  size?: 'xs' | 'sm' | 'md' | 'lg'
  className?: string
}

export function PlatformIcon({ platform, size = 'sm', className }: PlatformIconProps) {
  const sizeClass = cn(platformSizeClass[size], 'flex-shrink-0', className)
  const icon = platform ? platformIcons[platform] : undefined
  if (icon) return icon(sizeClass)
  return platformIcons.fallback(sizeClass)
}

